WITH filtered AS (SELECT id, carrier, shipped_date, cost, status, DATE_TRUNC('MONTH', delivered_date) delivered_date_period, ROUND(cost, 1) cost_rounded FROM shipments WHERE delivered_date > DATE '2023-09-11' AND carrier IS DISTINCT FROM 'DHL'), latest AS (SELECT * FROM filtered QUALIFY ROW_NUMBER() OVER (PARTITION BY status ORDER BY shipped_date NULLS FIRST, id) = 1), metrics AS (SELECT *, SUM(cost_rounded) OVER w_grp running_sum_cost_rounded, MAX(cost_rounded) OVER w_grp running_max_cost_rounded, AVG(cost_rounded) OVER w_grp running_avg_cost_rounded, AVG(cost) OVER (PARTITION BY status ORDER BY cost_rounded, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) cost_avg_5_prior FROM latest WINDOW w_grp AS (PARTITION BY status ORDER BY cost_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), gaps AS (SELECT *, CASE WHEN delivered_date_period - LAG(delivered_date_period) OVER (PARTITION BY status ORDER BY delivered_date_period, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM metrics), sessionized AS (SELECT id, cost, status, delivered_date_period, running_sum_cost_rounded, SUM(is_new_session) OVER (PARTITION BY status ORDER BY delivered_date_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, cost, delivered_date_period, running_sum_cost_rounded FROM sessionized ORDER BY delivered_date_period DESC;
